    mov.u32 %tid, %tid.x;
    mov.u32 %bid, %ctaid.x;
    mov.u32 %bdim, %ntid.x;
    mad.lo.u32 %idx, %bid, %bdim, %tid;          // idx = blockIdx.x * blockDim.x + threadIdx.x

    // ----- guard against out‑of‑range threads -------------------------------
    setp.ge.u32 %p, %idx, %batch;
    @%p bra DONE;

