    // each element is fp16 -> 2 bytes
    mul.wide.u32 %addr, %idx, %C;                // addr = idx * num_classes
    mul.wide.u32 %addr, %addr, 2;                // addr = addr * 2 (bytes)
    add.u64 %pred_ptr, %pred_ptr, %addr;        // %pred_ptr now points to predictions[idx,0]

    // ----- find max logit in the row (for numerical stability) -----------
    mov.f32 %max_val, -3.402823466e+38;         // -inf (float32)
    mov.u32 %j, 0;
MAX_LOOP:
    setp.ge.u32 %p, %j, %C;
    @%p bra MAX_DONE;
    mul.wide.u32 %addr, %j, 2;                  // offset = j * 2
    add.u64 %addr, %pred_ptr, %addr;
    ld.global.b16 %val16, [%addr];
    cvt.f32.f16 %tmp_u32, %val16;
    max.f32 %max_val, %max_val, %tmp_u32;
    add.u32 %j, %j, 1;
    bra MAX_LOOP;
MAX_DONE:

