    add.u64 %addr, %tgt_ptr, %addr;
    ld.global.u64 %tmp_u32, [%addr];
    cvt.u32.u64 %tmp_u32, %tmp_u32;            // target fits in 32‑bit

    // ----- load logit of the target class -----------------------------------
    mul.wide.u32 %addr, %tmp_u32, 2;           // target * sizeof(fp16)
    add.u64 %addr, %pred_ptr, %addr;
    ld.global.b16 %val16, [%addr];
    cvt.f32.f16 %logit_tgt, %val16;

    // ----- per‑sample loss = -logit_target + log_sum_exp -------------------
    sub.f32 %loss, %log_sum_exp, %logit_tgt;

