    def __init__(self):
        super().__init__()
        # load PTX module once
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, predictions: torch.Tensor, targets: torch.Tensor):
        """
        predictions : (B, C) fp16 tensor on CUDA
        targets    : (B,) int64 tensor on CUDA
        returns    : scalar loss tensor (fp16) on CUDA
        """
        batch, num_classes = predictions.shape
        # allocate a single‑float32 accumulator initialized to 0
        acc = torch.zeros(1, dtype=torch.float32, device='cuda')
        # launch parameters
        threads_per_block = 256
        blocks = (batch + threads_per_block - 1) // threads_per_block
        # arguments must be passed as a list of pointers / scalars
        args = [
            predictions.data_ptr(),
            targets.data_ptr(),
            acc.data_ptr(),
            batch,
            num_classes,
        ]
        ptx_launch(self.module, "cross_entropy_kernel",
                   grid=(blocks, 1, 1),
                   block=(threads_per_block, 1, 1),
                   args=args)
        # mean loss = sum / batch, cast to fp16
        loss = (acc.item() / batch)
        return torch.tensor(loss, dtype=torch.float16, device='cuda')
